import React from "react";
import { useCart } from "../contexts/CartContext";

export default function ProductCard({ product }) {
  const { addToCart } = useCart();

  return (
    <div style={cardStyles.card}>
      <img src={product.imageUrl} alt={product.name} style={cardStyles.image} />

      <h4 style={cardStyles.title}>{product.name}</h4>

      <p style={cardStyles.desc}>{product.description}</p>

      <p style={cardStyles.price}>
        ₹{product.price} <span style={cardStyles.stock}>• Stock: {product.stock}</span>
      </p>

      <p style={cardStyles.category}>{product.category}</p>

      <button
        onClick={() => addToCart(product)}
        style={cardStyles.button}
      >
        Add to Cart
      </button>
    </div>
  );
}

const cardStyles = {
  card: {
    borderRadius: "14px",
    padding: "16px",
    background: "#fff",
    width: "290px",
    boxShadow: "0 4px 14px rgba(0,0,0,0.08)",
    transition: "transform 0.2s ease, box-shadow 0.2s ease",
    cursor: "pointer",
  },
  image: {
    width: "100%",
    height: "180px",
    borderRadius: "10px",
    objectFit: "cover",
    marginBottom: "12px",
  },
  title: {
    fontSize: "18px",
    margin: "6px 0",
    fontWeight: 600,
    color: "#222",
  },
  desc: {
    fontSize: "14px",
    color: "#555",
    marginBottom: "10px",
  },
  price: {
    fontWeight: 600,
    marginBottom: "4px",
  },
  stock: {
    fontWeight: 400,
    color: "#333",
  },
  category: {
    fontSize: "13px",
    color: "#888",
    marginBottom: "12px",
  },
  button: {
    width: "100%",
    padding: "10px",
    background: "#0d6efd",
    border: "none",
    borderRadius: "6px",
    color: "white",
    fontWeight: "500",
    cursor: "pointer",
    transition: "0.2s",
  }
};
